import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"湘夫人","description":"","frontmatter":{"title":"湘夫人","date":"2026-11-24T00:00:00.000Z","seq":5,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"湘君","link":"/blogs/楚辞/湘君.html"},"next":{"text":"大司命","link":"/blogs/楚辞/大司命.html"}},"headers":[],"relativePath":"blogs/楚辞/湘夫人.md","filePath":"blogs/楚辞/湘夫人.md"}'),o={name:"blogs/楚辞/湘夫人.md"};function l(n,a,c,m,r,_){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="湘夫人" tabindex="-1">湘夫人 <a class="header-anchor" href="#湘夫人" aria-label="Permalink to &quot;湘夫人&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九歌</p><div class="poem"><p class="poem-stanza">帝子降兮北渚，目眇眇兮愁予</p><p class="poem-stanza">袅袅兮秋风，洞庭波兮木叶下</p><p class="poem-stanza">登白薠兮骋望，与佳期兮夕张</p><p class="poem-stanza">鸟何萃兮苹中，罾何为兮木上？</p><p class="poem-stanza">沅有茝兮醴有兰，思公子兮未敢言</p><p class="poem-stanza">荒忽兮远望，观流水兮潺湲</p><p class="poem-stanza">麋何食兮庭中，蛟何为兮水裔</p><p class="poem-stanza">朝驰余马兮江皋，夕济兮西澨</p><p class="poem-stanza">闻佳人兮召余，将腾驾兮偕逝</p><p class="poem-stanza">筑室兮水中，葺之兮荷盖</p><p class="poem-stanza">荪壁兮紫坛，播芳椒兮成堂</p><p class="poem-stanza">桂栋兮兰橑，辛夷楣兮药房</p><p class="poem-stanza">罔薜荔兮为帷，擗蕙櫋兮既张</p><p class="poem-stanza">白玉兮为镇，疏石兰兮为芳</p><p class="poem-stanza">芷葺兮荷屋，缭之兮杜衡</p><p class="poem-stanza">合百草兮实庭，建芳馨兮庑门</p><p class="poem-stanza">九嶷缤兮并迎，灵之来兮如云</p><p class="poem-stanza">捐余袂兮江中，遗余褋兮醴浦</p><p class="poem-stanza">搴汀洲兮杜若，将以遗兮远者</p><p class="poem-stanza">时不可兮骤得，聊逍遥兮容与！</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
